   const requestKey=tab+'|'+date+'|'+(patient?.id||''),retained=loadedKey===requestKey&&!!root.querySelector('[data-body]').textContent.trim();
   if(!retained)root.querySelector('[data-body]').innerHTML='<p class="pt-loading" role="status">불러오는 중입니다…</p>';else root.querySelector('[data-notice]').textContent='목록을 업데이트하는 중입니다…';
