  async function searchAllIntakes(){if(allIntakes){allIntakes=false;root.querySelector('[data-search-all]').textContent='이전 기록까지 검색';return;}if(intakeLoading||!next)return;allIntakes=true;const k=scope,epoch=revision;root.querySelector('[data-search-all]').textContent='검색 중지';while(allIntakes&&next&&current(k)&&epoch===revision&&tab==='intake'){if(!await moreIntakes())break;}if(epoch===revision&&current(k)&&tab==='intake'){allIntakes=false;const b=root.querySelector('[data-search-all]');b.textContent=next?'이전 기록까지 검색':'전체 기록 조회 완료';b.disabled=!next;}}

