   function list(){const query=intakeQuery.trim().toLowerCase(),invalid=intakeFrom&&intakeTo&&intakeFrom>intakeTo,shown=invalid?[]:intakes.filter(r=>{const day=new Date(r.created_at).toLocaleDateString('sv-SE');return (intakeFilter==='all'||intakeFilter==='pending'&&state(r)!=='reviewed'||state(r)===intakeFilter)&&(!intakeFrom||day>=intakeFrom)&&(!intakeTo||day<=intakeTo)&&[r.body.patientName,r.body.guardianName,r.body.purpose,r.body.symptoms].join(' ').toLowerCase().includes(query);});b.querySelector('[data-intake-count]').textContent=invalid?'시작일은 종료일보다 늦을 수 없습니다.':shown.length+'건 표시 · 불러온 기록 '+intakes.length+'건'+(next?' · 이전 기록 있음':' · 전체 조회 완료');b.querySelector('[data-intake-list]').innerHTML=shown.length?shown.map(r=>`<article class="pt-card"><div class="pt-heading"><div><h3>${esc(r.body.patientName)} <small>· 보호자 ${esc(r.body.guardianName)}</small></h3><p class="pt-intake-purpose">${esc(r.body.purpose)}</p></div><span class="pt-badge ${state(r)==='reviewed'?'pt-done':''}">${labels[state(r)]}</span></div>${r.body.symptoms?'<p class="pt-excerpt">'+esc(r.body.symptoms)+'</p>':''}<p class="pt-help">${stamp(r.created_at)} 제출${r.body.visitDate?' · 방문 희망일 '+esc(r.body.visitDate):''}${(r.addenda||[]).length?' · 추가 전달 '+r.addenda.length+'건':''}</p><div class="pt-card-footer"><small>${r.patient_id?'환자 연결됨':'보호자·환자 정보 대조 후 연결 필요'}</small><button data-intake="${esc(r.id)}">문진 확인</button></div></article>`).join(''):'<div class="pt-empty"><b>'+(invalid?'제출일 범위를 확인해주세요.':'현재 조건에 해당하는 사전문진이 없습니다.')+'</b><p class="pt-help">상태·검색어·기간을 바꾸거나 검색 조건을 초기화해주세요.</p></div>';b.querySelectorAll('[data-intake]').forEach(btn=>btn.onclick=()=>intakeDialog(btn.dataset.intake));}
